export const getModel = (m) => MODELS.find((x) => x.model.toLowerCase() === String(m).toLowerCase());
export const getModelsBySeries = (s) => MODELS.filter((x) => x.series === s);
export const specRows = (specs) => [
  { label: 'Size', value: specs.size },
  { label: 'Offset (ET)', value: specs.offset },
  { label: 'PCD', value: specs.pcd },
  { label: 'Weight', value: specs.weight },
];
